# 09_data_arch.py -- chapter 09's authored archetypes (the manufacturers, 09.2). Compiled and validated by
# 09-gen_data09.py into data/archetypes.yaml. Compact notation:
#   attrs: seven rung letters in the order might agility endurance wits intellect presence resolve
#          (A apex, H high, M mid, L low, F feeble, N none: T-09-2)
#   trained: letters of the defenses that add the band competence c_b (M A E W I P R); Guard always does
#   attacks: K(id, name, attr, off, harm, ...) where off = severity rungs relative to the band's standard
#            severity (T-09-3); heavy=True uses the band's heavy severity and always winds up (06.9.5)
#   armor: (kind, rung): natural none/hide/plate, worn light/medium/heavy (T-09-5)

def K(id, name, attr="might", off=0, harm=("harm.physical.cut",), bands=("band.engaged",), verb="verb.strike",
      heavy=False, shape=None, site=None, riders=(), cost=1, weight="natural", primary=False):
    return dict(id=id, name=name, attr=attr, off=off, harm=list(harm), bands=list(bands), verb=verb, heavy=heavy,
                shape=shape, site=site, riders=list(riders), action_cost=cost, weight=weight, primary=primary)

BITE = lambda off=0, riders=(), primary=True: K("bite", "Bite", "might", off, ("harm.physical.pierce",), riders=riders, primary=primary)
CLAW = lambda off=0, riders=(), primary=False: K("claws", "Claws", "might", off, ("harm.physical.cut",), riders=riders, primary=primary)
GORE = lambda off=0, riders=(): K("gore", "Gore or trample", "might", off, ("harm.physical.pierce",), riders=riders, primary=True)
SLAM = lambda off=0, riders=(), primary=True: K("slam", "Slam", "might", off, ("harm.physical.crush",), riders=riders, primary=primary)
SWORD = lambda off=0, attr="might": K("blade", "Sword or axe", attr, off, ("harm.physical.cut",), weight="one_handed", primary=True)
SPEAR = lambda off=0: K("spear", "Spear", "might", off, ("harm.physical.pierce",), bands=("band.engaged", "band.close"), weight="one_handed", primary=True)
DAGGER = lambda off=0, riders=(): K("knife", "Knife", "agility", off, ("harm.physical.pierce",), riders=riders, weight="light", primary=True)
BOW = lambda off=0, riders=(): K("bow", "Bow", "agility", off, ("harm.physical.pierce",), bands=("band.close", "band.near", "band.far"), weight="bow", riders=riders)
SLING = lambda off=0: K("sling", "Sling", "agility", off, ("harm.physical.crush",), bands=("band.close", "band.near"), weight="bow")
MAUL = lambda off=0, riders=(): K("maul", "Great maul or club", "might", off, ("harm.physical.crush",), heavy=True, weight="heavy", riders=riders, site="body")

def A(id, name, ctags, harm, deeds, attrs, trained, attacks, *, summary, orgs=(), mind="animal", speaks=False, tongue=None,
      size="medium", bands=(1, 2), roles=("soldier",), armor=("natural", "none"), no_gaps=None, powers=(), traits=(),
      cannot=(), behaviors=(), nerve="steady", brk="flee", disposition="drive_off", kill_when=(), captive_fate=None,
      can_bargain=False, dread=None, lethal=False, reaction=None, reaction_roll=False, pace=1, loot=None, purse="none",
      gear=(), harvest=None, absorb=None, weak=None, tells=None, lore=("deed.lore.bestiary", "common"), terrain=(),
      group=None, objective=None, beh_role=None, fearless=False):
    return dict(id=id, name=name, creature_tags=list(ctags), harm_tags=list(harm), evidence_tags=list(deeds),
                org_tags=list(orgs), attrs=attrs, trained=trained, attacks=list(attacks), summary=summary, mind=mind,
                speaks=speaks, tongue=tongue, size=size, bands=list(bands), roles=list(roles), armor=armor,
                no_gaps=(armor[0] == "natural") if no_gaps is None else no_gaps, powers=list(powers),
                traits=list(traits), cannot=list(cannot), behaviors=list(behaviors), nerve=("fearless" if fearless else nerve),
                brk=brk, disposition=disposition, kill_when=list(kill_when), captive_fate=captive_fate,
                can_bargain=can_bargain, dread=dread, lethal=lethal, reaction=reaction, reaction_roll=reaction_roll,
                pace=pace, loot=loot or {}, purse=purse, gear=list(gear), harvest=harvest, absorb=absorb or {}, weak=weak,
                tells=tells or {}, lore=lore, terrain=list(terrain), group=group or {}, objective=objective, beh_role=beh_role)

E = lambda eid, **p: {"effect_id": eid, "params": p}
RES = lambda *tags: E("eff.harm_resistance", factor=0.5, harm_tags=list(tags))
VULN = lambda *tags: E("eff.harm_vulnerability", factor=2, harm_tags=list(tags))
IMM = lambda *conds: E("eff.condition_immunity", forbid={"conditions": list(conds)}, target="self")
T = lambda presence, wounded, breaking, weak_hint=None, windup=None: dict(presence=presence, wounded=wounded, breaking=breaking, weak_hint=weak_hint, windup=windup)

